questions.model_answer:
function analyzeReleaseHealth(releases) {
  const first = releases[0];
  const prev = releases[releases.length - 2];
  const last = releases[releases.length - 1];
  const firstMarginalKloc = first.totalKloc;
  const lastMarginalKloc = last.totalKloc - prev.totalKloc;
  const firstCostPerKloc = first.payroll / firstMarginalKloc;
  const lastCostPerKloc = last.payroll / lastMarginalKloc;
  const costPerKlocMultiplier = Number((lastCostPerKloc / firstCostPerKloc).toFixed(1));
  const marginalOutputRatio = Number((lastMarginalKloc / firstMarginalKloc).toFixed(2));
  return {
    costPerKlocMultiplier,
    marginalOutputRatio,
    isSignatureOfMess: costPerKlocMultiplier >= 10 && marginalOutputRatio <= 0.25
  };
}

