questions.model_answer:
function verifyGormanExperiment(runs) {
  const tdd = runs.filter(r => r.usedTdd).map(r => r.minutes);
  const nonTdd = runs.filter(r => !r.usedTdd).map(r => r.minutes);
  const avgTddMinutes = Number((tdd.reduce((a, b) => a + b, 0) / tdd.length).toFixed(1));
  const avgNonTddMinutes = Number((nonTdd.reduce((a, b) => a + b, 0) / nonTdd.length).toFixed(1));
  const percentFaster = Math.round(((avgNonTddMinutes - avgTddMinutes) / avgNonTddMinutes) * 100);
  const slowestTddBeatFastestNonTdd = Math.max(...tdd) < Math.min(...nonTdd);
  return { avgTddMinutes, avgNonTddMinutes, percentFaster, slowestTddBeatFastestNonTdd };
}

