questions.model_answer:
function createOrderPricer(taxPolicyFn, discountPolicyFn) {
  return function priceOrder(items) {
    const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
    const discount = discountPolicyFn(subtotal, items);
    const taxable = Math.max(0, subtotal - discount);
    const tax = taxPolicyFn(taxable, items);
    return {
      subtotal,
      discount,
      tax,
      total: Number((taxable + tax).toFixed(2))
    };
  };
}
